                b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
                recon[i]=(cur[i]+paeth(a,b,c))&0xFF
        out[y*stride:(y+1)*stride]=recon
        prev=recon
    for ty in range(h):
        line=""
