func parseSpecs(args []string) ([]data.Spec, error) {
	var specs []data.Spec
	for _, arg := range args {
		// Split by "+"
		parts := strings.Split(arg, "+")
		var fields []data.Field
		for _, p := range parts {
			var f data.Field
			if idx := strings.Index(p, ":"); idx >= 0 {
				optStr := p[:idx]
				path := p[idx+1:]
				// options split by ","
				opts := strings.Split(optStr, ",")
				for _, o := range opts {
					if o == "counter" {
						f.Counter = true
					} else if o == "marker" {
						f.Marker = true
					} else {
						return nil, fmt.Errorf("invalid field option: %s", o)
					}
				}
				f.Path = path
			} else {
				f.Path = p
			}
			fields = append(fields, f)
		}
		specs = append(specs, data.Spec{Fields: fields})
	}
	return specs, nil
}

