	_TCSETS = 0x5402
	_TIOCGWINSZ = 0x5413
)

type winsize struct {
	Row uint16
	Col uint16
	Xpixel uint16
	Ypixel uint16
}

type termios struct {
	Iflag uint32
	Oflag uint32
	Cflag uint32
	Lflag uint32
	Line uint8
	Cc [32]uint8
	Ispeed uint32
	Ospeed uint32
}

func isTTY(f *os.File) bool {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), _TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	return errno == 0
}

func getWinsize(f *os.File) (int, int, error) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), _TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, errno
	}
	return int(ws.Row), int(ws.Col), nil
}

func setRaw(fd uintptr) (termios, error) {
	var t termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, _TCGETS, uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return t, errno
	}
	old := t
	t.Iflag &^= 0x400 | 0x100 | 0x2 | 0x10 | 0x20
	t.Oflag &^= 0x1
	t.Cflag &^= 0x30
	t.Cflag |= 0x30
	t.Lflag &^= 0x2 | 0x8 | 0x1 | 0x8000
	t.Cc[6] = 1
	t.Cc[5] = 0
	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL, fd, _TCSETS, uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return old, errno
	}
	return old, nil
}

func readOne(fd uintptr) []byte {
	buf := make([]byte, 4096)
	n, err := syscall.Read(int(fd), buf)
	if err != nil || n <= 0 {
		return []byte{}
	}
	return buf[:n]
}

const (
	termIterm = "iterm"
