	s := string(resp)
	if len(s) < 4 || s[0] != 0x1b || s[1] != '[' || s[2] != '?' {
		return false
	}
	ok := false
	for _, p := range []string{"\x1b[?62;", "\x1b[?63;", "\x1b[?64;", "\x1b[?65;"} {
		if strings.HasPrefix(s, p) {
