	}
	return specs, nil
}

func main() {
	signal.Ignore(syscall.SIGINT, syscall.SIGTERM)
	detectedTerm = detectTerminal()
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n")
		fmt.Fprintf(os.Stderr, "\nOPTIONS:\n")
		flag.PrintDefaults()
		fmt.Fprintf(os.Stderr, "\nFIELD_SPEC: [<option>[,<option>...]:]path\n")
		fmt.Fprintf(os.Stderr, "  option:\n")
		fmt.Fprintf(os.Stderr, "    - counter: Computes the difference with the last value. The value must increase monotonically.\n")
		fmt.Fprintf(os.Stderr, "    - marker: When the value is none-zero, a vertical line is drawn.\n")
		fmt.Fprintf(os.Stderr, "  path:\n")
		fmt.Fprintf(os.Stderr, "    JSON field path (eg: field.sub-field).\n")
	}
	flag.Parse()
	if detectedTerm == termNone {
		fmt.Fprintf(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n")
		os.Exit(1)
	}
	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}
	specs, err := parseSpecs(args)
	if err != nil {
		fmt.Fprintf(os.Stdout, "jplot:  Cannot parse spec:  %s\n", err.Error())
		os.Exit(1)
	}
	if *flagURL == "" && isTTY(os.Stdin) {
