import subprocess as sp, pty, fcntl, termios, struct, time, os
def test_panic(args):
    master, slave = pty.openpty()
    env=dict(os.environ); env["TERM_PROGRAM"]="iTerm.app"
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0, 0))
    p=sp.Popen(["/tmp/jplot_test"]+args, stdin=sp.PIPE, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave)
    try: p.stdin.write(b'{"foo": 1}\n'); p.stdin.flush()
    except: pass
    flags = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    out=b""; start=time.time(); sent=False; closed=False
    while time.time()-start < 4:
        try:
            d=os.read(master, 16384)
            if d:
                out+=d
                print(f"READ {d[:400]!r}")
                if b"ReportCellSize" in d and not sent:
                    # Only respond if query (no =)? Our new binary's query is same. Respond.
                    if b"ReportCellSize=" not in d:
                        time.sleep(0.05); os.write(master, b"\x1b]1337;ReportCellSize=20;10\x07"); sent=True
        except OSError: pass
        if not closed and time.time()-start>2.0:
            try: p.stdin.close()
            except: pass
            closed=True
        if p.poll() is not None:
            print(f"exit {p.poll()}")
            time.sleep(0.3)
            try:
                while True:
                    d=os.read(master,16384)
                    if not d: break
                    out+=d; print(f"DRAIN {d[:500]!r}")
            except: pass
            break
        time.sleep(0.05)
    print(f"args={args} exit={p.poll()} out_tail={out[-600:]!r}")
    try: p.kill(); p.wait(timeout=2)
    except: pass
    os.close(master)

for args in [["-rows=-1", "foo"], ["-steps=-1", "foo"], ["-steps=0", "foo"], ["-steps=1", "foo"]]:
    test_panic(args)
